insert into legal_concept (concept_key, label, parent_key, definition, aliases, contract_types, sort_order, taxonomy_version) values
    ('PARTIES_AND_DEFINITIONS', 'Parties and definitions', NULL, NULL, '{}'::text[], '{}'::text[], 1, 1),
    ('TERM_AND_TERMINATION', 'Term and termination', NULL, NULL, '{}'::text[], '{}'::text[], 2, 1),
    ('CONFIDENTIALITY', 'Confidentiality', NULL, NULL, '{}'::text[], '{}'::text[], 3, 1),
    ('DATA_PROTECTION', 'Data protection', NULL, NULL, '{}'::text[], '{}'::text[], 4, 1),
    ('COMMERCIAL', 'Commercial', NULL, NULL, '{}'::text[], '{}'::text[], 5, 1),
    ('SERVICES_DELIVERY', 'Services delivery', NULL, NULL, '{}'::text[], '{}'::text[], 6, 1),
    ('IP_AND_LICENSING', 'Ip and licensing', NULL, NULL, '{}'::text[], '{}'::text[], 7, 1),
    ('WARRANTIES', 'Warranties', NULL, NULL, '{}'::text[], '{}'::text[], 8, 1),
    ('LIABILITY_AND_INDEMNITY', 'Liability and indemnity', NULL, NULL, '{}'::text[], '{}'::text[], 9, 1),
    ('RESTRICTIVE_COVENANTS', 'Restrictive covenants', NULL, NULL, '{}'::text[], '{}'::text[], 10, 1),
    ('COMPLIANCE', 'Compliance', NULL, NULL, '{}'::text[], '{}'::text[], 11, 1),
    ('DISPUTES_AND_LAW', 'Disputes and law', NULL, NULL, '{}'::text[], '{}'::text[], 12, 1),
    ('GENERAL', 'General', NULL, NULL, '{}'::text[], '{}'::text[], 13, 1),
    ('DOCUMENT_STRUCTURE', 'Document structure', NULL, NULL, '{}'::text[], '{}'::text[], 14, 1),
    ('PARTIES', 'Parties and roles', 'PARTIES_AND_DEFINITIONS', 'Identifies each legal entity and the role it holds, such as discloser or recipient, controller or processor, or licensor and licensee.', ARRAY['Parties', 'Between', 'Party Details', 'Parties to this Agreement', 'Recitals', 'Background', 'Background and Recitals']::text[], ARRAY['MNDA', 'ONDA', 'MSA', 'SAAS', 'DPA', 'SOW', 'SWL']::text[], 101, 1),
    ('DEFINITIONS_INTERPRETATION', 'Definitions and interpretation', 'PARTIES_AND_DEFINITIONS', 'Defines capitalised terms and sets rules for reading the agreement, such as headings, gender, and whether ''including'' is exhaustive.', ARRAY['Definitions', 'Interpretation', 'Interpretation Clause', 'Defined Terms', 'Construction', 'Business Day Definitions']::text[], ARRAY['MNDA', 'ONDA', 'MSA', 'SAAS', 'DPA', 'SOW', 'SWL']::text[], 102, 1),
    ('EFFECTIVE_DATE', 'Effective date', 'PARTIES_AND_DEFINITIONS', 'The date the agreement takes effect. It is not the signing date and not how long the agreement lasts.', ARRAY['Effective Date', 'Agreement Date', 'Dated As Of', 'Date of Agreement', 'Effective as of', 'Date of Effectiveness']::text[], ARRAY['MNDA', 'ONDA', 'MSA', 'SAAS', 'DPA', 'SOW', 'SWL']::text[], 103, 1),
    ('TERM', 'Term', 'TERM_AND_TERMINATION', 'How long the agreement lasts, from the start date to the end date. Not how long one particular duty lasts.', ARRAY['Term', 'Duration', 'Term of Agreement', 'Initial Term', 'Expiry', 'Expiration Date', 'End Date']::text[], ARRAY['MNDA', 'ONDA', 'MSA', 'SAAS', 'DPA', 'SOW', 'SWL']::text[], 104, 1),
    ('RENEWAL', 'Renewal', 'TERM_AND_TERMINATION', 'Automatic or optional extension of the term and the notice needed to stop it. Applies where the agreement has no fixed end.', ARRAY['Renewal', 'Auto-Renewal', 'Automatic Renewal', 'Renewal Term', 'Evergreen', 'Notice of Non-Renewal', 'Renewal Period']::text[], ARRAY['MSA', 'SAAS', 'SOW', 'SWL']::text[], 105, 1),
    ('TERMINATION_FOR_CAUSE', 'Termination for cause', 'TERM_AND_TERMINATION', 'Right to end the agreement early for material breach, insolvency or unlawful conduct, with any cure period. Also covers suspending service while a breach is uncured.', ARRAY['Termination', 'Termination for Breach', 'Material Breach', 'Termination for Cause', 'Insolvency', 'Breach and Termination', 'Suspension', 'Suspension of Services']::text[], ARRAY['MNDA', 'ONDA', 'MSA', 'SAAS', 'DPA', 'SOW', 'SWL']::text[], 106, 1),
    ('TERMINATION_FOR_CONVENIENCE', 'Termination for convenience', 'TERM_AND_TERMINATION', 'Right for either party to end the agreement early without any cause, usually on written notice of a stated period and sometimes against a fee. Applies only where the agreement grants the right.', ARRAY['Termination for Convenience', 'Termination Without Cause', 'Early Termination', 'Early Termination Fee']::text[], ARRAY['MSA', 'SAAS', 'SOW', 'SWL']::text[], 107, 1),
    ('SUSPENSION', 'Suspension', 'TERM_AND_TERMINATION', 'A right to pause the services or a party''s performance for a time, for example for unpaid fees or a security risk, without ending the agreement.', ARRAY['Suspension', 'Suspension of Services', 'Right to Suspend', 'Service Suspension']::text[], ARRAY['MSA', 'SAAS', 'SOW', 'SWL']::text[], 108, 1),
    ('SURVIVAL', 'Survival', 'TERM_AND_TERMINATION', 'Names the clauses that keep operating after the agreement ends, and for how long. Not the length of the agreement itself.', ARRAY['Survival', 'Surviving Provisions', 'Surviving Obligations', 'Effect of Termination', 'Continuing Obligations', 'Survival of Certain Provisions']::text[], ARRAY['MNDA', 'ONDA', 'MSA', 'SAAS', 'DPA', 'SOW', 'SWL']::text[], 109, 1),
    ('CONFIDENTIAL_INFORMATION_SCOPE', 'Confidential information scope', 'CONFIDENTIALITY', 'What counts as confidential information, including oral or marked disclosures, and the exclusions for public, already known, independently developed and third-party sourced material.', ARRAY['Confidential Information', 'Definition of Confidential Information', 'Exclusions from Confidential Information', 'What Is Not Confidential', 'Oral Disclosures', 'Marked Confidential', 'Confidentiality Exceptions']::text[], ARRAY['MNDA', 'ONDA', 'MSA', 'SAAS', 'SOW', 'SWL']::text[], 110, 1),
    ('CONFIDENTIALITY_OBLIGATIONS', 'Confidentiality obligations', 'CONFIDENTIALITY', 'The receiving party''s duties: use the information only as allowed, protect it to at least reasonable care, and tell the discloser if it is lost or disclosed.', ARRAY['Use and Protection of Confidential Information', 'Non-Use and Non-Disclosure', 'Obligations of Receiving Party', 'Standard of Care', 'Security of Confidential Information', 'Notice of Unauthorised Disclosure', 'Confidentiality Undertakings']::text[], ARRAY['MNDA', 'ONDA', 'MSA', 'SAAS', 'DPA', 'SOW', 'SWL']::text[], 111, 1),
    ('PERMITTED_PURPOSE', 'Permitted purpose', 'CONFIDENTIALITY', 'Limits the use of confidential information to a stated purpose, such as evaluating a transaction, and bans every other use.', ARRAY['Purpose', 'Permitted Purpose', 'Limited Use', 'Evaluation Purpose', 'Use for Purpose Only', 'Purpose Limitation', 'Purpose of Disclosure']::text[], ARRAY['MNDA', 'ONDA', 'MSA', 'SAAS', 'SOW', 'SWL']::text[], 112, 1),
    ('ONWARD_DISCLOSURE', 'Disclosure to representatives', 'CONFIDENTIALITY', 'Who else may see the information, such as employees, advisers, affiliates and financing sources, the conditions attached, and who is responsible for their acts.', ARRAY['Representatives', 'Disclosure to Representatives', 'Permitted Recipients', 'Affiliates', 'Need to Know', 'Onward Disclosure', 'Disclosure to Affiliates', 'Professional Advisers']::text[], ARRAY['MNDA', 'ONDA', 'MSA', 'SAAS', 'SOW', 'SWL']::text[], 113, 1),
    ('COMPELLED_DISCLOSURE', 'Compelled disclosure', 'CONFIDENTIALITY', 'Permission to disclose where a court, regulator or law requires it, including a foreign government''s demand for data held overseas, with notice to the other party. Not the governing law clause.', ARRAY['Disclosures Required by Law', 'Required Disclosure', 'Compelled Disclosure', 'Legal Process', 'Regulatory Disclosure', 'Subpoena', 'Court Order', 'Required by Law', 'Compelled Disclosure by Law', 'Government Access', 'Government Demand', 'CLOUD Act', 'FOIA', 'National Security Demand']::text[], ARRAY['MNDA', 'ONDA', 'MSA', 'SAAS', 'SOW', 'SWL']::text[], 114, 1),
    ('RESIDUALS', 'Residuals', 'CONFIDENTIALITY', 'A right to use confidential information that staff happen to retain in unaided memory, despite the use and confidentiality duties.', ARRAY['Residuals', 'Residual Information', 'Residual Knowledge', 'Unaided Memory', 'Residual Knowledge Rights', 'Memory Residuals']::text[], ARRAY['MNDA', 'ONDA', 'MSA', 'SAAS', 'SWL']::text[], 115, 1),
    ('CONFIDENTIALITY_PERIOD', 'Confidentiality period', 'CONFIDENTIALITY', 'How long the confidentiality duty lasts after disclosure or termination, including any longer or indefinite period for trade secrets. Not the agreement''s own length.', ARRAY['Term of Confidentiality', 'Confidentiality Period', 'Duration of Confidentiality', 'Trade Secrets', 'Protection of Trade Secrets', 'Continuing Confidentiality', 'Obligations After Termination']::text[], ARRAY['MNDA', 'ONDA', 'MSA', 'SAAS', 'DPA', 'SOW', 'SWL']::text[], 116, 1),
    ('RETURN_OR_DESTRUCTION', 'Return or destruction', 'CONFIDENTIALITY', 'On exit, returning, deleting or destroying confidential material or personal data, including copies and backups, subject to a retention exception. In a DPA the controller chooses.', ARRAY['Return or Destruction of Confidential Information', 'Return of Materials', 'Return or Deletion of Personal Data', 'Deletion or Return', 'Certificate of Destruction', 'Retention Exception', 'Backups', 'Destruction of Copies']::text[], ARRAY['MNDA', 'ONDA', 'MSA', 'SAAS', 'DPA', 'SOW', 'SWL']::text[], 117, 1),
    ('NO_COMMITMENT', 'No commitment', 'CONFIDENTIALITY', 'States that disclosure creates no obligation to do a deal, grants no licence and makes no representation. Not the warranty disclaimer, and not a positive grant of rights, which is LICENSE_GRANT.', ARRAY['No Obligation', 'No Commitment', 'No Licence', 'No License', 'No Obligation to Proceed', 'Discussions Only', 'Information Only']::text[], ARRAY['MNDA', 'ONDA']::text[], 118, 1),
    ('PROCESSING_DETAILS', 'Details of processing', 'DATA_PROTECTION', 'The subject matter, duration, nature and purpose of the processing, the types of personal data and the categories of data subjects, usually set out in a table.', ARRAY['Details of Processing', 'Description of Processing', 'Subject Matter and Duration', 'Nature and Purpose', 'Scope of Processing', 'Categories of Personal Data', 'Categories of Data Subjects', 'Types of Personal Data']::text[], ARRAY['DPA', 'SAAS', 'MSA']::text[], 119, 1),
    ('PROCESSOR_DUTIES', 'Processor duties', 'DATA_PROTECTION', 'What the processor must do: follow documented instructions, keep the data confidential, not use it for its own purposes, and pass the terms to its personnel.', ARRAY['Processing on Instructions', 'Documented Instructions', 'Personnel Confidentiality', 'Restriction on Processing', 'No Own Use', 'Processor Obligations', 'Instructions of the Controller']::text[], ARRAY['DPA', 'SAAS', 'MSA']::text[], 120, 1),
    ('CONTROLLER_OBLIGATIONS', 'Controller obligations', 'DATA_PROTECTION', 'What the controller must do for the arrangement: hold the rights and a lawful basis in the data, give clear instructions, supply the data, and tell the processor if the processing changes.', ARRAY['Controller Obligations', 'Responsibilities of the Controller', 'Controller Warranties', 'Customer Obligations', 'Lawful Basis', 'Changes to Processing', 'Provision of Data']::text[], ARRAY['DPA', 'SAAS', 'MSA']::text[], 121, 1),
    ('SECURITY_MEASURES', 'Security measures', 'DATA_PROTECTION', 'The technical and organisational safeguards the provider must keep, such as encryption and access control, any named certification like SOC 2, and business continuity, backup and disaster recovery with recovery time and point objectives.', ARRAY['Security', 'Security Measures', 'Technical and Organisational Measures', 'TOMs', 'Information Security', 'Security Standards', 'Security Requirements', 'SOC 2', 'ISO 27001', 'PCI DSS', 'Penetration Testing', 'Security Audit', 'Business Continuity', 'Disaster Recovery', 'Backup and Restore', 'RPO', 'RTO', 'Restore Testing', 'Non-Production']::text[], ARRAY['DPA', 'SAAS', 'MSA', 'SWL']::text[], 122, 1),
    ('BREACH_NOTIFICATION', 'Breach notification', 'DATA_PROTECTION', 'Duty to tell the controller or customer quickly after a security or personal data incident, what the notice must contain, and who pays for it.', ARRAY['Data Breach Notification', 'Breach Notification', 'Security Incident', 'Incident Notification', 'Notification of Security Incident', 'Notice of Security Incident', 'Security Incident Reporting', 'Notify of Breach']::text[], ARRAY['DPA', 'SAAS', 'MSA']::text[], 123, 1),
    ('SUB_PROCESSORS', 'Sub-processors', 'DATA_PROTECTION', 'Whether the processor may appoint other processors, how authorisation works, notice of changes and objection rights, and flow-down of the same duties.', ARRAY['Sub-processors', 'Subprocessors', 'Sub-processing', 'Authorised Sub-processors', 'Use of Other Processors', 'Objection to Sub-processors', 'Sub-processor List', 'Sub-processor Notification']::text[], ARRAY['DPA', 'SAAS', 'MSA']::text[], 124, 1),
    ('DATA_SUBJECT_AND_REGULATORY_ASSISTANCE', 'Data subject and regulatory assistance', 'DATA_PROTECTION', 'Processor help with data subject rights requests, regulator enquiries, impact assessments and breach consultations, usually charged at agreed rates.', ARRAY['Data Subject Requests', 'Assistance', 'DSAR', 'Assistance with Data Subject Rights', 'Data Protection Impact Assessment', 'Prior Consultation', 'Regulatory Cooperation', 'Assistance with Investigations']::text[], ARRAY['DPA', 'SAAS', 'MSA']::text[], 125, 1),
    ('INTERNATIONAL_TRANSFERS', 'International transfers', 'DATA_PROTECTION', 'The conditions and legal mechanism for sending personal data outside its origin country, such as the EU or UK standard contractual clauses, and any transfer risk assessment.', ARRAY['International Transfers', 'Cross-Border Transfers', 'Restricted Transfers', 'Standard Contractual Clauses', 'SCCs', 'Data Localisation', 'Data Residency', 'Data Location', 'Adequacy', 'Transfer Impact Assessment', 'Sub-processors Outside the EEA']::text[], ARRAY['DPA', 'SAAS', 'MSA']::text[], 126, 1),
    ('CUSTOMER_DATA_OWNERSHIP_AND_USE', 'Customer data ownership and use', 'DATA_PROTECTION', 'Who owns customer data and what the provider may do with it, including aggregation, de-identification and service analytics. Anything naming training, a model or machine learning is AI_AND_MODEL_TRAINING.', ARRAY['Customer Data', 'Data Ownership', 'Ownership of Customer Data', 'Usage Data', 'Aggregated Data', 'Service Data', 'Derived Data', 'De-identified Data', 'Anonymised Data']::text[], ARRAY['DPA', 'SAAS', 'MSA', 'SOW']::text[], 127, 1),
    ('AI_AND_MODEL_TRAINING', 'AI and model training', 'DATA_PROTECTION', 'Whether the provider may use customer data, inputs, prompts or outputs to train, fine-tune or improve any AI or machine-learning model, and whether the customer can opt out. Applies to personal data or not.', ARRAY['AI Addendum', 'AI Training', 'Machine Learning', 'Model Improvement', 'Generative AI', 'AI Features', 'Model Training', 'No Training', 'Training Data', 'Artificial Intelligence']::text[], ARRAY['DPA', 'SAAS', 'MSA', 'SWL']::text[], 128, 1),
    ('FEES_AND_PAYMENT', 'Fees and payment', 'COMMERCIAL', 'Prices, invoicing, payment deadlines, late-payment interest, expenses, price rises during the term, discounts, how usage is metered and disputed, and overage above the committed volume. Not a promise about other customers, which is MOST_FAVORED_NATION.', ARRAY['Fees', 'Payment', 'Pricing', 'Charges', 'Invoicing', 'Payment Terms', 'Late Payment Interest', 'Expenses', 'Reimbursement', 'Price Increases', 'Price Restrictions', 'Discounts', 'Rebates', 'Usage Charges', 'Set-Off', 'Overage Charges', 'Usage Metering', 'Metering', 'Usage Caps', 'Revenue Share', 'Profit Share', 'Commission', 'Referral Fee']::text[], ARRAY['MSA', 'SAAS', 'SOW', 'SWL']::text[], 129, 1),
    ('VOLUME_COMMITMENTS', 'Volume commitments', 'COMMERCIAL', 'Minimum purchase, spend or metered usage a customer commits to, tiered price steps, and true-up at the end of the term. Not seat, user or site caps, which are LICENSE_RESTRICTIONS.', ARRAY['Minimum Commitment', 'Minimum Purchase', 'Committed Spend', 'Volume Restriction', 'Minimum Fees', 'Minimum Spend', 'Capacity Limits', 'True Up', 'True-Up', 'Tiered Pricing', 'Volume Discount']::text[], ARRAY['MSA', 'SAAS', 'SWL']::text[], 130, 1),
    ('TAXES', 'Taxes', 'COMMERCIAL', 'Which party bears which taxes, withholding on payments, and whether the payer must gross up.', ARRAY['Taxes', 'Tax Withholding', 'Withholding Taxes', 'Withholdings', 'Gross-Up', 'Value Added Tax', 'VAT', 'Sales Tax', 'Tax on Payments']::text[], ARRAY['MSA', 'SAAS', 'SOW', 'SWL']::text[], 131, 1),
    ('EXCLUSIVITY', 'Exclusivity', 'COMMERCIAL', 'Rights granted to one party on an exclusive basis, or limits on dealing with competitors, including any carve-outs.', ARRAY['Exclusivity', 'Exclusive Dealing', 'Exclusive Rights', 'Exclusive Provider', 'Sole Supplier', 'Reseller Agreement', 'Non-Competition Exception', 'Appointment of Resellers']::text[], ARRAY['MSA', 'SAAS', 'SOW', 'SWL']::text[], 132, 1),
    ('MOST_FAVORED_NATION', 'Most favoured nation', 'COMMERCIAL', 'A promise that pricing and terms are no less favourable than those given to other customers or partners.', ARRAY['Most Favored Nation', 'Most Favoured Nation', 'MFN', 'Most Favoured Customer', 'Most Favored Customer', 'Price Parity', 'Preferred Pricing']::text[], ARRAY['MSA', 'SAAS']::text[], 133, 1),
    ('ROFR_ROFO_ROFN', 'Right of first refusal or offer', 'COMMERCIAL', 'A right to be offered, or to match, a proposed sale, licence or transfer before it goes to a third party.', ARRAY['Right of First Refusal', 'ROFR', 'Right of First Offer', 'ROFO', 'Right of First Negotiation', 'ROFN', 'Pre-emption Right', 'Right to Match']::text[], ARRAY['MSA', 'SAAS', 'SWL']::text[], 134, 1),
    ('STANDING_OBLIGATIONS', 'Standing and negotiation obligations', 'COMMERCIAL', 'Obligations to stay in discussions: negotiate in good faith, negotiate exclusively for a period, or pay a break fee if the deal ends. Not the statement that disclosure creates no obligation, which is NO_COMMITMENT.', ARRAY['Standing', 'Good Faith', 'Obligation to Negotiate', 'Exclusivity Period', 'Standstill', 'Break Fee', 'Expenses on Termination', 'Negotiation Obligations']::text[], ARRAY['MNDA', 'ONDA', 'MSA']::text[], 135, 1),
    ('SCOPE_AND_DELIVERABLES', 'Scope and deliverables', 'SERVICES_DELIVERY', 'What the provider must deliver: services, deliverables, milestones and dates, assumptions and exclusions, plus what the customer must supply in return.', ARRAY['Scope of Work', 'Scope of Services', 'Description of Services', 'Services', 'Deliverables', 'Milestones', 'Timeline', 'Project Plan', 'Customer Responsibilities', 'Client Responsibilities', 'Client Dependencies', 'Assumptions', 'Exclusions', 'Dependencies', 'In Scope']::text[], ARRAY['MSA', 'SAAS', 'SOW']::text[], 136, 1),
    ('ACCEPTANCE', 'Acceptance', 'SERVICES_DELIVERY', 'How a deliverable is accepted: review period, test criteria, deemed acceptance, reasons for rejection, cure, and any limit on the number of rejections.', ARRAY['Acceptance', 'Acceptance Testing', 'Acceptance Criteria', 'Testing and Acceptance', 'Deemed Acceptance', 'Rejection and Cure', 'Acceptance Procedure', 'Delivery and Acceptance', 'Acceptance Sign-Off']::text[], ARRAY['MSA', 'SOW']::text[], 137, 1),
    ('CHANGE_CONTROL', 'Change control', 'SERVICES_DELIVERY', 'How scope, price or schedule changes are requested, approved, priced and recorded, and who may approve them.', ARRAY['Change Control', 'Change Requests', 'Change Orders', 'Change Management', 'Scope Change', 'Change Procedure', 'Change in Scope', 'Change in Fees']::text[], ARRAY['MSA', 'SAAS', 'SOW']::text[], 138, 1),
    ('PROJECT_GOVERNANCE', 'Project governance', 'SERVICES_DELIVERY', 'Who decides what for the engagement: steering committee or working group, meeting cadence, escalation path and decision authority.', ARRAY['Project Governance', 'Governance', 'Steering Committee', 'Working Group', 'Governance Model', 'Project Meetings', 'Management Meetings', 'Decision Authority', 'Escalation Path', 'Project Team', 'Governance Arrangements']::text[], ARRAY['MSA', 'SOW']::text[], 139, 1),
    ('SERVICE_LEVELS', 'Service levels', 'SERVICES_DELIVERY', 'Measurable performance targets such as uptime or response times, how they are measured and reported, and remedies such as service credits and chronic failure.', ARRAY['Service Levels', 'SLA', 'Service Level Agreement', 'Availability', 'Uptime', 'Service Credits', 'Performance Standards', 'Availability Credits', 'Chronic Failure', 'Service Level Reporting', 'Performance Targets', 'Commitment Levels']::text[], ARRAY['MSA', 'SAAS', 'SWL']::text[], 140, 1),
    ('SUPPORT_AND_MAINTENANCE', 'Support and maintenance', 'SERVICES_DELIVERY', 'Support and maintenance after delivery: hours and channels, fixing defects, software updates and upgrades, and which version of the product is supported.', ARRAY['Support', 'Support Services', 'Support and Maintenance', 'Maintenance', 'Maintenance Services', 'Updates and Upgrades', 'Release Updates', 'Product Updates', 'Upgrade Path', 'Bug Fixes', 'Support Hours', 'Patch Management']::text[], ARRAY['MSA', 'SAAS', 'SWL']::text[], 141, 1),
    ('SUBCONTRACTING_PERSONNEL', 'Subcontracting and personnel', 'SERVICES_DELIVERY', 'Whether the provider may use subcontractors, key person commitments and replacement rights, and responsibility for them. Not the same as sub-processors.', ARRAY['Subcontractors', 'Subcontracting', 'Personnel', 'Key Personnel', 'Key Persons', 'Staffing', 'Personnel Replacement', 'Contractor Personnel', 'Use of Subcontractors']::text[], ARRAY['MSA', 'SAAS', 'SOW']::text[], 142, 1),
    ('TRANSITION_ASSISTANCE', 'Transition assistance', 'SERVICES_DELIVERY', 'Help after termination to move the customer and its data elsewhere, including export format, duration, rates and any wind-down charges.', ARRAY['Post-Termination Services', 'Transition Assistance', 'Transition Services', 'Exit Assistance', 'Exit Plan', 'Data Export', 'Wind-Down', 'Migration Assistance', 'Offboarding', 'Termination Assistance', 'Export of Data']::text[], ARRAY['MSA', 'SAAS', 'SOW']::text[], 143, 1),
    ('FEATURE_DEPRECATION', 'Feature deprecation and end of life', 'SERVICES_DELIVERY', 'Notice before a feature, version or service is withdrawn or end-of-lifed, roadmap and beta-feature commitments, and any right to refuse renewal or exit because of a deprecation. Not uptime targets or defect fixing.', ARRAY['Deprecation', 'End of Life', 'End-of-Life', 'Discontinuation', 'Feature Withdrawal', 'Roadmap', 'Beta Features', 'Preview Features', 'Early Access', 'Sunsetting a Feature']::text[], ARRAY['MSA', 'SAAS', 'SWL']::text[], 144, 1),
    ('BUSINESS_CONTINUITY', 'Business continuity and disaster recovery', 'SERVICES_DELIVERY', 'Plans and duties to keep the services running, or restore them, after a serious disruption, such as backups, recovery time targets and continuity testing.', ARRAY['Business Continuity', 'Disaster Recovery', 'Business Continuity and Disaster Recovery', 'Backup and Recovery', 'Resilience']::text[], ARRAY['MSA', 'SAAS', 'SOW', 'SWL']::text[], 145, 1),
    ('ASSUMPTIONS_AND_DEPENDENCIES', 'Assumptions and dependencies', 'SERVICES_DELIVERY', 'What the price and plan assume, and what the customer must provide or do, and what happens to time and cost if an assumption proves wrong.', ARRAY['Assumptions', 'Dependencies', 'Assumptions and Dependencies', 'Customer Dependencies', 'Customer Responsibilities', 'Client Obligations']::text[], ARRAY['SOW', 'MSA']::text[], 146, 1),
    ('IP_OWNERSHIP_WORK_PRODUCT', 'IP ownership of work product', 'IP_AND_LICENSING', 'Who owns new deliverables and work product, including any assignment of rights and what happens to jointly created material.', ARRAY['Intellectual Property', 'IP Ownership', 'Ownership of Deliverables', 'Work Product', 'Assignment of IP', 'Joint Ownership', 'Developments', 'Ownership of Work Product']::text[], ARRAY['MSA', 'SAAS', 'SOW', 'SWL']::text[], 147, 1),
    ('PRE_EXISTING_IP', 'Pre-existing IP', 'IP_AND_LICENSING', 'Each party keeps its own background or pre-existing IP, and any licence the other party needs to use it for the deliverables.', ARRAY['Pre-Existing IP', 'Background IP', 'Pre-Existing Materials', 'Pre-Existing Technology', 'Existing Materials', 'Provider Materials', 'Incorporated Materials', 'Foreground and Background IP']::text[], ARRAY['MSA', 'SAAS', 'SOW', 'SWL']::text[], 148, 1),
    ('LICENSE_GRANT', 'License grant', 'IP_AND_LICENSING', 'The rights the licensor gives: which software or materials, how many copies or users, the delivery model, the term, and use by affiliates.', ARRAY['License Grant', 'Grant of Licence', 'Licence Grant', 'Licensed Software', 'Licensee', 'License Terms', 'Affiliate Use', 'Non-Transferable Licence', 'Concurrent Users', 'Deployment Rights', 'License Keys']::text[], ARRAY['MSA', 'SAAS', 'SWL']::text[], 149, 1),
    ('LICENSE_RESTRICTIONS', 'License restrictions', 'IP_AND_LICENSING', 'Limits on use: no copying, reverse engineering, sublicensing or benchmarking beyond the licence, and caps by seat, user, site or field of use.', ARRAY['Use Restrictions', 'Restrictions on Use', 'Prohibited Uses', 'Reverse Engineering', 'No Sublicensing', 'Seats', 'Users', 'Site Licence', 'Field of Use', 'Copying Restrictions', 'Usage Limits', 'Number of Users', 'Benchmarking', 'Benchmark Restrictions', 'No Benchmarking']::text[], ARRAY['MSA', 'SAAS', 'SWL']::text[], 150, 1),
    ('PERPETUAL_OR_UNLIMITED_LICENSE', 'Perpetual or unlimited licence', 'IP_AND_LICENSING', 'A licence that is perpetual or irrevocable, or unlimited in users, copies or usage, and whether it ever ends.', ARRAY['Perpetual License', 'Perpetual Licence', 'Irrevocable License', 'Unlimited License', 'All-You-Can-Eat', 'Lifetime License', 'Enterprise License', 'Subscription License', 'Perpetual Entitlement']::text[], ARRAY['SWL']::text[], 151, 1),
    ('SOURCE_CODE_ESCROW', 'Source code escrow', 'IP_AND_LICENSING', 'Deposit of source code or build materials with a third party, and the release events, update duty, verification and fees.', ARRAY['Source Code Escrow', 'Escrow Agreement', 'Escrow Release', 'Deposit Materials', 'Release Events', 'Release Conditions', 'Source Code Deposit', 'Verifiability', 'Escrow Agent']::text[], ARRAY['SWL', 'SAAS', 'MSA']::text[], 152, 1),
    ('THIRD_PARTY_AND_OPEN_SOURCE', 'Third-party and open-source components', 'IP_AND_LICENSING', 'Terms and obligations for bundled third-party and open-source software, including copyleft terms, and who is responsible for it.', ARRAY['Third-Party Software', 'Third-Party Materials', 'Third-Party Components', 'Third-Party Licences', 'Open Source', 'Open Source Software', 'Copyleft', 'Free and Open Source Software', 'Software Bill of Materials']::text[], ARRAY['MSA', 'SAAS', 'SWL']::text[], 153, 1),
    ('FEEDBACK_LICENSE', 'Feedback licence', 'IP_AND_LICENSING', 'A licence to use suggestions, ideas or feedback about the product or service, usually free of charge and royalty-free. Not the same as residuals.', ARRAY['Feedback', 'Feedback Licence', 'Suggestions', 'Ideas', 'Improvement Feedback', 'Contributions', 'Feedback Rights', 'Suggestions and Feedback']::text[], ARRAY['MSA', 'SAAS', 'SWL']::text[], 154, 1),
    ('COVENANT_NOT_TO_SUE', 'Covenant not to sue', 'IP_AND_LICENSING', 'A promise not to bring IP infringement claims against the other party for its own licensed or authorised use.', ARRAY['Covenant Not to Sue', 'No Assertion', 'Non-Assertion', 'Patent Non-Assertion', 'No Patent Infringement Suit', 'Patent Licence Covenant']::text[], ARRAY['MSA', 'SAAS', 'SWL']::text[], 155, 1),
    ('AI_OUTPUT_RIGHTS', 'AI output rights', 'IP_AND_LICENSING', 'Who owns or may use content the service generates from customer inputs, including prompts, completions and embeddings, and whether output is licensed or assigned. Not the provider''s right to train models, which is AI_AND_MODEL_TRAINING.', ARRAY['AI Output', 'Output Ownership', 'Generated Content', 'Generated Outputs', 'Output Licence', 'Output License', 'Model Output', 'Machine-Generated Content', 'Outputs']::text[], ARRAY['MSA', 'SAAS', 'SOW', 'SWL']::text[], 156, 1),
    ('WARRANTY_PERFORMANCE', 'Performance warranty', 'WARRANTIES', 'A promise that the services or software conform to the specification or documentation and are performed with reasonable skill and care, and how long it lasts.', ARRAY['Warranties', 'Performance Warranty', 'Conformance', 'Warranty Period', 'Warranty Duration', 'Professional and Workmanlike', 'Service Warranty', 'Fitness for Purpose']::text[], ARRAY['MSA', 'SAAS', 'SOW', 'SWL']::text[], 157, 1),
