    ('REPRESENTATIONS_AUTHORITY', 'Representations and authority', 'WARRANTIES', 'Statements of present fact at signing: authority to sign, due formation, no conflicting obligations, and no malicious code. Not an ongoing duty to comply with law.', ARRAY['Representations', 'Authority to Execute', 'Mutual Representations', 'Due Formation', 'No Conflicts', 'Organisation and Good Standing', 'No Malicious Code', 'Mutual Warranties', 'Validity of Agreement']::text[], ARRAY['MNDA', 'ONDA', 'MSA', 'SAAS', 'DPA', 'SOW', 'SWL']::text[], 159, 1),
    ('WARRANTY_DISCLAIMER', 'Warranty disclaimer', 'WARRANTIES', 'Excludes implied warranties and limits express ones to what the agreement says, often stating the information or service is provided as is.', ARRAY['Disclaimer', 'Disclaimer of Warranties', 'As Is', 'As-Is', 'No Other Warranties', 'Implied Warranties', 'Exclusion of Implied Warranties', 'No Warranty', 'No Representation']::text[], ARRAY['MNDA', 'ONDA', 'MSA', 'SAAS', 'DPA', 'SOW', 'SWL']::text[], 160, 1),
    ('LIMITATION_OF_LIABILITY', 'Limitation of liability', 'LIABILITY_AND_INDEMNITY', 'The ceiling on what each party can recover in total: the amount or formula, whether it is mutual, and what it covers.', ARRAY['Limitation of Liability', 'Liability Cap', 'Cap on Liability', 'Aggregate Liability', 'Aggregate Cap', 'Limitation of Aggregate Liability', 'Liability Ceiling', 'Overall Limitation']::text[], ARRAY['MNDA', 'MSA', 'SAAS', 'SOW', 'SWL', 'DPA']::text[], 161, 1),
    ('UNCAPPED_LIABILITY', 'Uncapped liability', 'LIABILITY_AND_INDEMNITY', 'The claims that sit outside the cap, or under a higher super-cap, such as IP indemnity, data breach, confidentiality breach, gross negligence or wilful misconduct.', ARRAY['Uncapped Liability', 'Exclusions from Cap', 'Carve-Outs', 'Super Cap', 'Excluded Claims', 'Unlimited Liability', 'Liability Exclusions', 'Excluded from Limitation']::text[], ARRAY['MNDA', 'MSA', 'SAAS', 'SOW', 'SWL', 'DPA']::text[], 162, 1),
    ('EXCLUSION_OF_DAMAGES', 'Exclusion of damages', 'LIABILITY_AND_INDEMNITY', 'The waiver of indirect, consequential, special and punitive damages, usually also naming lost profit, lost revenue and loss of data.', ARRAY['Consequential Damages', 'Indirect Damages', 'Exclusion of Damages', 'Waiver of Consequential Damages', 'Special Damages', 'Punitive Damages', 'Lost Profits', 'Lost Revenue', 'Loss of Data']::text[], ARRAY['MNDA', 'ONDA', 'MSA', 'SAAS', 'DPA', 'SOW', 'SWL']::text[], 163, 1),
    ('LIQUIDATED_DAMAGES', 'Liquidated damages', 'LIABILITY_AND_INDEMNITY', 'A fixed or agreed sum payable when a stated event happens, such as late delivery, instead of proving the actual loss. Not uptime service credits, which are SERVICE_LEVELS.', ARRAY['Liquidated Damages', 'Agreed Damages', 'Fixed Damages', 'Delay Damages', 'Milestone Penalties', 'Penalties for Delay']::text[], ARRAY['MSA', 'SAAS', 'SOW', 'SWL']::text[], 164, 1),
    ('INDEMNIFICATION', 'Indemnification', 'LIABILITY_AND_INDEMNITY', 'A duty to defend and pay third-party claims for stated triggers, such as a data breach or property damage, with notice, defence control and settlement rules.', ARRAY['Indemnification', 'Indemnity', 'Indemnities', 'Hold Harmless', 'Defence and Indemnity', 'Conduct of Claims', 'Defence Costs', 'Claims Procedure', 'Third Party Claims', 'Indemnity Procedure']::text[], ARRAY['MSA', 'SAAS', 'SOW', 'SWL', 'DPA']::text[], 165, 1),
