    ('NON_COMPETE', 'Non-compete', 'RESTRICTIVE_COVENANTS', 'A restraint on competing with the other party in a stated market, territory or field for a stated period. Not a grant of exclusive rights, which is EXCLUSIVITY.', ARRAY['Non-Compete', 'Non-Competition', 'Non-Competitive', 'Competitive Restriction', 'Restriction on Competition', 'Non-Compete Period', 'Competition with the Company']::text[], ARRAY['MSA', 'SAAS', 'SOW', 'SWL']::text[], 168, 1),
    ('NON_SOLICIT_EMPLOYEES', 'Non-solicitation of employees', 'RESTRICTIVE_COVENANTS', 'A restraint on soliciting or hiring the other party''s employees or contractors for a stated period. Not a restraint on customers.', ARRAY['No-Solicit of Employees', 'Non-Solicitation of Employees', 'Non-Solicit of Personnel', 'Employee Non-Solicit', 'No Hire', 'No-Poach', 'Anti-Raid', 'Recruitment Restriction', 'No-Solicitation of Key Personnel']::text[], ARRAY['MNDA', 'ONDA', 'MSA', 'SOW']::text[], 169, 1),
